			"Office.CustomXMLNode": {"displayName":"CustomXMLNode","members":[{"name":"AppendChildNode","kind":"method","signature":"AppendChildNode([Name As String], [NamespaceURI As String], [NodeType As MsoCustomXMLNodeType], [NodeValue As String])","doc":{"summary":"Appends a single node as the last child under the context element node in the tree.","params":[],"source":"external"}},{"name":"AppendChildSubtree","kind":"method","signature":"AppendChildSubtree(XML As String)","doc":{"summary":"Adds a subtree as the last child under the context element node in the tree.","params":[],"source":"external"}},{"name":"Application","kind":"property","returns":"Object","doc":{"summary":"Gets an Application object that represents the container application for a CustomXMLNode object. Read-only.","params":[],"source":"external"}},{"name":"Attributes","kind":"property","returns":"Office.CustomXMLNodes","doc":{"summary":"Gets a CustomXMLNodes collection representing the attributes of the current element in the current node. Read-only.","params":[],"source":"external"}},{"name":"BaseName","kind":"property","returns":"String","doc":{"summary":"Gets the base name of the node without the namespace prefix, if one exists, in the Document Object Model (DOM). Read-only.","params":[],"source":"external"}},{"name":"ChildNodes","kind":"property","returns":"Office.CustomXMLNodes","doc":{"summary":"Gets a CustomXMLNodes collection containing all of the child elements of the current node. Read-only.","params":[],"source":"external"}},{"name":"Creator","kind":"property","returns":"Long","doc":{"summary":"Gets a 32-bit integer that indicates the application in which the CustomXMLNode object was created. Read-only.","params":[],"source":"external"}},{"name":"Delete","kind":"method","signature":"Delete()","doc":{"summary":"Deletes the current node from the tree (including all of its children, if any exist).","params":[],"source":"external"}},{"name":"FirstChild","kind":"property","returns":"Office.CustomXMLNode","doc":{"summary":"Gets a CustomXMLNode object corresponding to the first child element of the current node. If the node has no child elements (or if it isn't of type msoCustomXMLNodeElement), returns Nothing. Read-only.","params":[],"source":"external"}},{"name":"HasChildNodes","kind":"method","returns":"Boolean","signature":"HasChildNodes() As Boolean","doc":{"summary":"Gets True if the current element node has child element nodes.","params":[],"source":"external"}},{"name":"InsertNodeBefore","kind":"method","signature":"InsertNodeBefore([Name As String], [NamespaceURI As String], [NodeType As MsoCustomXMLNodeType], [NodeValue As String], [NextSibling As CustomXMLNode])","doc":{"summary":"Inserts a new node just before the context node in the tree.","params":[],"source":"external"}},{"name":"InsertSubtreeBefore","kind":"method","signature":"InsertSubtreeBefore(XML As String, [NextSibling As CustomXMLNode])","doc":{"summary":"Inserts the specified subtree into the location just before the context node.","params":[],"source":"external"}},{"name":"LastChild","kind":"property","returns":"Office.CustomXMLNode","doc":{"summary":"Gets a CustomXMLNode object corresponding to the last child element of the current node. If the node has no child elements (or if it is not of type msoCustomXMLNodeElement), the property returns Nothing. Read-only.","params":[],"source":"external"}},{"name":"NamespaceURI","kind":"property","returns":"String","doc":{"summary":"Gets the unique address identifier for the namespace of the CustomXMLNode object. Read-only.","params":[],"source":"external"}},{"name":"NextSibling","kind":"property","returns":"Office.CustomXMLNode","doc":{"summary":"Gets the next sibling node (element, comment, or processing instruction) of the current node. If the node is the last sibling at its level, the property returns Nothing. Read-only.","params":[],"source":"external"}},{"name":"NodeType","kind":"property","returns":"MsoCustomXMLNodeType","doc":{"summary":"Gets the type of the current node. Read-only.","params":[],"source":"external"}},{"name":"NodeValue","kind":"property","returns":"String","doc":{"summary":"Gets or sets the value of the current node. Read/write.","params":[],"source":"external"}},{"name":"OwnerDocument","kind":"property","returns":"Object","doc":{"summary":"Gets the object representing the Microsoft Excel workbook, PowerPoint presentation, or Word document associated with this node. Read-only.","params":[],"source":"external"}},{"name":"OwnerPart","kind":"property","returns":"Office.CustomXMLPart","doc":{"summary":"Gets the object representing the part associated with this node. Read-only.","params":[],"source":"external"}},{"name":"Parent","kind":"property","returns":"Object","doc":{"summary":"Gets the Parent object for the CustomXMLNode object. Read-only.","params":[],"source":"external"}},{"name":"ParentNode","kind":"property","returns":"Office.CustomXMLNode","doc":{"summary":"Gets the parent element node of the current node. If the current node is at the root level, the property returns Nothing. Read-only.","params":[],"source":"external"}},{"name":"PreviousSibling","kind":"property","returns":"Office.CustomXMLNode","doc":{"summary":"Gets the previous sibling node (element, comment, or processing instruction) of the current node. If the current node is the first sibling at its level, the property returns Nothing. Read-only.","params":[],"source":"external"}},{"name":"RemoveChild","kind":"method","signature":"RemoveChild(Child As CustomXMLNode)","doc":{"summary":"Removes the specified child node from the tree.","params":[],"source":"external"}},{"name":"ReplaceChildNode","kind":"method","signature":"ReplaceChildNode(OldNode As CustomXMLNode, [Name As String], [NamespaceURI As String], [NodeType As MsoCustomXMLNodeType], [NodeValue As String])","doc":{"summary":"Removes the specified child node (and its subtree) from the main tree, and replaces it with a different node in the same location.","params":[],"source":"external"}},{"name":"ReplaceChildSubtree","kind":"method","signature":"ReplaceChildSubtree(XML As String, OldNode As CustomXMLNode)","doc":{"summary":"Removes the specified node (and its subtree) from the main tree, and replaces it with a different subtree in the same location.","params":[],"source":"external"}},{"name":"SelectNodes","kind":"method","returns":"Office.CustomXMLNodes","signature":"SelectNodes(XPath As String) As CustomXMLNodes","doc":{"summary":"Selects a collection of nodes matching an XPath expression. This method differs from the CustomXMLPart.SelectNodes method in that the XPath expression will be evaluated starting with the 'expression' node as the context node.","params":[],"source":"external"}},{"name":"SelectSingleNode","kind":"method","returns":"Office.CustomXMLNode","signature":"SelectSingleNode(XPath As String) As CustomXMLNode","doc":{"summary":"Selects a single node from a collection matching an XPath expression. This method differs from the CustomXMLPart.SelectSingleNode method in that the XPath expression will be evaluated starting with the 'expression' node as the context node.","params":[],"source":"external"}},{"name":"Text","kind":"property","returns":"String","doc":{"summary":"Gets or sets the text for the current node. Read/write.","params":[],"source":"external"}},{"name":"XML","kind":"property","returns":"String","doc":{"summary":"Gets the XML representation of the current node and its children, if any exist. Read-only.","params":[],"source":"external"}},{"name":"XPath","kind":"property","returns":"String","doc":{"summary":"Gets a String with the canonicalized XPath for the current node. If the node is no longer in the Document Object Model (DOM), the property returns an error message. Read-only.","params":[],"source":"external"}}],"provenance":"Represents an XML node in a tree in a document. The CustomXMLNode object is a member of the CustomXMLNodes collection."},
