			"Office.FileDialogFilter": {"displayName":"FileDialogFilter","members":[{"name":"Application","kind":"property","returns":"Object","doc":{"summary":"Gets an Application object that represents the container application for the FileDialogFilter object (you can use this property with an Automation object to return that object's container application). Read-only.","params":[],"source":"external"}},{"name":"Creator","kind":"property","returns":"Long","doc":{"summary":"Gets a 32-bit integer that indicates the application in which the FileDialogFilter object was created. Read-only.","params":[],"source":"external"}},{"name":"Description","kind":"property","returns":"String","doc":{"summary":"Gets the description of each Filter object as a String value. The description is the text that is displayed in a file dialog box. Read-only.","params":[],"source":"external"}},{"name":"Extensions","kind":"property","returns":"String","doc":{"summary":"Gets a value containing the extensions that determine which files are displayed in a file dialog box for each Filter object. Read-only.","params":[],"source":"external"}},{"name":"Parent","kind":"property","returns":"Object","doc":{"summary":"Gets the Parent object for the FileDialogFilter object. Read-only.","params":[],"source":"external"}}],"provenance":"Represents a file filter in a file dialog box displayed through the FileDialog object. Each file filter determines which files are displayed in the file dialog box."},
