			"Office.FileDialogSelectedItems": {"displayName":"FileDialogSelectedItems","members":[{"name":"Application","kind":"property","returns":"Object","doc":{"summary":"Gets an Application object that represents the container application for the FileDialogSelectedItems object (you can use this property with an Automation object to return that object's container application). Read-only.","params":[],"source":"external"}},{"name":"Count","kind":"property","returns":"Long","doc":{"summary":"Gets a Long indicating the number of items in the FileDialogSelectedItems collection. Read-only.","params":[],"source":"external"}},{"name":"Creator","kind":"property","returns":"Long","doc":{"summary":"Gets a 32-bit integer that indicates the application in which the FileDialogSelectedItems object was created. Read-only.","params":[],"source":"external"}},{"name":"Item","kind":"method","returns":"String","signature":"Item(Index As Long) As String","doc":{"summary":"Gets a String that corresponds to the path of one of the files by the _Index_ that the user selected from a file dialog box that was displayed by using the Show method of the FileDialog object.","params":[],"source":"external"}},{"name":"Parent","kind":"property","returns":"Object","doc":{"summary":"Gets the Parent object for the FileDialogSelectedItems object. Read-only.","params":[],"source":"external"}}],"provenance":"A collection of String values that correspond to the paths of the files or folders that a user has selected from a file dialog box displayed through the FileDialog object."},
